FUNCTION_BLOCK FB
VAR_INPUT
    startBtn : BOOL;
    resetBtn : BOOL;
    doneSensor : BOOL;
    targetVol : REAL;
    flowVol : REAL;
END_VAR
VAR_OUTPUT
    valveOpen : BOOL;
    fillsToday : INT;
END_VAR
VAR
    startBtn_prev : BOOL;
    resetBtn_prev : BOOL;
    is_filling : BOOL;
    accumulated_volume : REAL;
    waiting_for_done : BOOL;
    start_rising : BOOL;
    reset_rising : BOOL;
END_VAR

// 边沿检测
start_rising := startBtn AND NOT startBtn_prev;
reset_rising := resetBtn AND NOT resetBtn_prev;

IF reset_rising THEN
    // 复位优先
    fillsToday := 0;
    valveOpen := FALSE;
    accumulated_volume := 0.0;
    waiting_for_done := FALSE;
    is_filling := FALSE;
ELSE
    // 处理启动
    IF start_rising AND NOT is_filling THEN
        // 开始新瓶
        waiting_for_done := FALSE;
        is_filling := TRUE;
        accumulated_volume := 0.0;
    END_IF;

    // 灌装处理
    IF is_filling THEN
        // 累加本周期流量
        accumulated_volume := accumulated_volume + flowVol;
        // 判断是否达标
        IF accumulated_volume >= targetVol THEN
            // 达标，关阀
            valveOpen := FALSE;
            is_filling := FALSE;
            waiting_for_done := TRUE;
        ELSE
            // 未达标，保持开阀
            valveOpen := TRUE;
        END_IF;
    ELSE
        // 非灌装状态
        valveOpen := FALSE;
        // 满瓶确认处理
        IF waiting_for_done AND doneSensor THEN
            // 计数加1，饱和保护
            IF fillsToday < 32767 THEN
                fillsToday := fillsToday + 1;
            END_IF;
            waiting_for_done := FALSE;
        END_IF;
    END_IF;
END_IF;

// 更新历史
startBtn_prev := startBtn;
resetBtn_prev := resetBtn;

END_FUNCTION_BLOCK

